import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`qa-tester`,heroTitle:`QA test your app in minutes`,heroSubtitle:`Perplexity Computer explores your app, identifies bugs, tests edge cases, and delivers a QA report with reproducible steps — automatically.`,inputUrlCta:`Test my app`,inputUrlPlaceholder:`e.g. https://app.example.com`,inputUrlPrefill:`Go to {url} and perform a comprehensive QA test. (1) Explore every major user flow — signup, login, core features, settings, and navigation — documenting each step and interaction. (2) Test edge cases including empty states, long text inputs, special characters, rapid clicks, and browser back/forward behavior. (3) Check responsive behavior across desktop, tablet, and mobile viewport sizes — flagging layout breaks, overflow issues, and touch target problems. (4) Identify UI/UX issues including inconsistent styling, broken links, missing loading states, error handling gaps, and accessibility violations. (5) Test form validation — required fields, email formats, password rules, and error messaging. (6) Document every bug with a clear title, severity level, reproducible steps, expected vs actual behavior, and a screenshot or description of the visual state. (7) Deliver a prioritized QA report organized by severity — critical, major, minor, and cosmetic.`,heroOverlaySteps:[`Exploring every major user flow, page, and interaction`,`Testing edge cases, form validation, and error handling`,`Documenting bugs with reproducible steps and severity levels`,`Prioritized QA report with bug details and screenshots — ready to fix`],generatingSteps:[`Visiting {url} to explore your app and map all user flows`,`Designing an agent to test edge cases, responsive behavior, and form validation`,`Configuring bug documentation with reproducible steps and severity classification`,`Setting up QA report with prioritized issues and actionable fix recommendations`],featureSectionTitle:`From URL to QA report`,featureCardTitles:[`Connects to your dev stack`,`Outputs you can fix`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`GitHub, Jira, Slack, Linear — Computer plugs into your tools so bug reports, screenshots, and QA findings flow into one workflow.`,`Bug reports. Screenshots. Reproducible steps. Severity rankings. Computer delivers a complete QA report your engineering team can execute immediately.`],capabilitySectionTitle:`Your QA engineer, on autopilot`,capabilitySectionSubtitle:`Paste your app URL, step away, get back a complete QA report.`,capabilityCards:[{title:`App Exploration`,description:`Computer can navigate every page and user flow in your app — testing signup, login, core features, settings, and navigation systematically.`},{title:`Edge Case Testing`,description:`Computer can test empty states, long inputs, special characters, rapid interactions, and browser navigation — catching the bugs your users would find.`},{title:`Bug Reports`,description:`Computer can document every issue with a clear title, severity, reproducible steps, expected vs actual behavior, and visual description.`},{title:`Connect Your Tools`,description:`Computer can read from GitHub, Jira, Linear, Slack, and more — build workflows that turn QA findings into tracked issues automatically.`},{title:`Remember & Learn`,description:`Computer can remember past test results, known issues, and your app architecture across sessions — so every QA pass builds on prior findings.`},{title:`Regression Monitoring`,description:`Computer can re-test critical flows on a schedule — and alert you when a previously working feature breaks or a fixed bug reappears.`}]});export{t as default};
